+---
+"Create data stream with lifecycle":
+  - skip:
+      version: " - 8.7.99"
+      reason: "Data lifecycle in index templates was added after 8.7"
+  - do:
+      indices.put_index_template:
+        name: template-with-lifecycle
+        body:
+          index_patterns: [dlm-managed-data-stream]
+          template:
+            settings:
+              index.number_of_replicas: 0
+            lifecycle:
+              data_retention: "30d"
+          data_stream: {}
+  - do:
+      indices.create_data_stream:
+        name: dlm-managed-data-stream
+  - is_true: acknowledged
+
+  - do:
+      indices.get_data_stream:
+        name: "dlm-managed-data-stream"
+  - match: { data_streams.0.name: dlm-managed-data-stream }
+  - match: { data_streams.0.timestamp_field.name: '@timestamp' }
+  - match: { data_streams.0.generation: 1 }
+  - length: { data_streams.0.indices: 1 }
+  - match: { data_streams.0.indices.0.index_name: '/\.ds-dlm-managed-data-stream-(\d{4}\.\d{2}\.\d{2}-)?000001/' }
+  - match: { data_streams.0.status: 'GREEN' }
+  - match: { data_streams.0.template: 'template-with-lifecycle' }
+  - match: { data_streams.0.hidden: false }
+  - match: { data_streams.0.lifecycle.data_retention: '30d' }
