+                if (apiName.equals("indices.resolve_index")) {
+                    // in this specific api, the index parameter is called "name"
+                    parameterName = "name";
+                }
+                String originalIndices = params.get(parameterName);
+                String expandedIndices = REMOTE_CLUSTER_NAME + ":*";
